class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        // Breaking change (EF Core 9): Migrate() now manages its own transactions
        // and throws if called inside a user-initiated transaction.
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

