using Microsoft.EntityFrameworkCore;

// Demonstrates the two Cosmos DB breaking changes in EF Core 9.

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "CatalogDb",
            cosmosOptions =>
            {
                // Breaking change #1: Synchronous Cosmos I/O now throws by default.
                // If you have sync queries (e.g. .ToList(), .First()) that cannot be
                // converted to async yet, opt back in explicitly:
                cosmosOptions.AllowSynchronousIO();
            });
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #2: The default discriminator property changed from
        // "Discriminator" to "$type" in EF Core 9. Existing documents already
        // store "Discriminator", so override the default to keep compatibility:
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}

